7.query:
timeseries {
  input = sum(gen_ai.client.token.usage, {gen_ai.token.type="input"}),
  output = sum(gen_ai.client.token.usage, {gen_ai.token.type="output"}),
  cache_read = sum(gen_ai.client.token.usage, {gen_ai.token.type="cache_read"}),
  cache_creation = sum(gen_ai.client.token.usage, {gen_ai.token.type="cache_creation"})
}, interval:10m

8.query:
timeseries {
  cache_read = sum(gen_ai.client.token.usage, {gen_ai.token.type="cache_read"}),
  input = sum(gen_ai.client.token.usage, {gen_ai.token.type="input"})
}
| fieldsAdd cache_rate = if(input > 0, 100 * cache_read / input, 0)
